diff --git a/overrides/app/components/ui-kits/organisms/zimmProductGallery/index.tsx b/overrides/app/components/ui-kits/organisms/zimmProductGallery/index.tsx
new file mode 100644
index 0000000..63a6d87
--- /dev/null
+++ b/overrides/app/components/ui-kits/organisms/zimmProductGallery/index.tsx
@@ -0,0 +1,334 @@
+import React, { useEffect, useMemo, useRef, useState } from 'react';
+import { VisuallyHidden, chakra, useMultiStyleConfig } from '@chakra-ui/react';
+import { defineMessages, useIntl } from 'react-intl';
+import { ZimmButton } from '../../atoms/zimmButton';
+import { ZimmMediaTile } from '../../atoms/zimmMediaTile';
+import type { ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
+import { getDesktopLayoutCounts } from './getDesktopLayoutCounts';
+
+const messages = defineMessages({
+  openGallery: { id: 'product_gallery.trigger.open', defaultMessage: 'Open image gallery' },
+  openGalleryAt: {
+    id: 'product_gallery.trigger.open_at',
+    defaultMessage: 'Open image gallery, image {index} of {total}',
+  },
+  galleryButton: { id: 'product_gallery.trigger.label', defaultMessage: 'Gallery +{count}' },
+  // No confirmed Figma frame for this state yet (SFCC-731 AC 1/2/4's plain button, counts of
+  // 3/4/6) — reasoned default pending sign-off, same as the layout counts in
+  // getDesktopLayoutCounts.ts.
+  galleryButtonPlain: { id: 'product_gallery.trigger.label_plain', defaultMessage: 'Gallery' },
+  goToSlide: { id: 'product_gallery.dot.label', defaultMessage: 'Go to image {index} of {total}' },
+  currentSlide: { id: 'product_gallery.live.current', defaultMessage: '{alt}. Image {index} of {total}.' },
+});
+
+const ZIMM_PRODUCT_GALLERY_RECIPE = 'ZimmProductGallery';
+
+// Item-count layout (which items stack vs grid, grid row width) lives in
+// getDesktopLayoutCounts.ts, per SFCC-731's Acceptance Criteria. Only the grid's own column
+// count is needed here, for chunking gridItems into rows.
+const DESKTOP_GRID_COLUMNS = 2;
+
+// SFCC-731 AC 19 — DIS responsive widths per tile type. `base: '100vw'` everywhere below `lg`
+// (every tile is full-bleed there); the `lg` ceiling is each tile type's own Figma reference
+// width (zimmMediaTile.css.ts's own comment: stacked 902px, grid 450px) — a fluid column can
+// render slightly under this on an ultra-wide viewport, which is a fine trade-off against
+// shipping full raw resolution unconditionally.
+const STACKED_ITEM_WIDTHS = { base: '100vw', lg: 902 };
+const GRID_ITEM_WIDTHS = { base: '100vw', lg: 450 };
+const COMPACT_ITEM_WIDTHS = { base: '100vw' };
+
+// ZimmMediaTile (ui-kits/atoms) owns the canonical media-item shape now — re-exported here so
+// existing importers of this module (product-view/mapImageGroupsToGalleryMedia.ts, this
+// component's own stories/tests) don't need to change their import path.
+export type { ZimmGalleryPhotoItem, ZimmGalleryVideoItem, ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
+
+type ZimmProductGalleryProps = {
+  /** Ordered photo/video sequence. Video renders as a positional slot only — see ZimmGalleryVideoItem. */
+  media: ZimmGalleryMediaItem[];
+  /**
+   * Fires when the shopper wants to view the full gallery — clicking anywhere on the gallery,
+   * or the "Gallery +N" button. The overlay itself is a separate component (SFCC-187 "PDP –
+   * Image Gallery Open State"), out of scope here — this only surfaces the intent to open it.
+   */
+  onOpenGallery?: () => void;
+  /**
+   * Defers loading of the first item too, not just the rest. Pass true for set/bundle child
+   * contexts where the gallery isn't the primary viewport content — mirrors the base
+   * ImageGallery's `lazy` prop this component replaces on the PDP.
+   */
+  lazy?: boolean;
+  /** Hides the "Gallery"/"Gallery +N" trigger button entirely, regardless of media count. */
+  showGalleryButton?: boolean;
+  /**
+   * SFCC-731 AC 19 — DIS quality (`q` param, 0-100) for every tile's responsive image request.
+   * Forwarded to `ZimmMediaTile`/`buildDisImageSrc`. Defaults to that function's own default
+   * (80) when omitted.
+   */
+  imageQuality?: number;
+};
+
+const chunk = <TItem,>(items: TItem[], size: number): TItem[][] => {
+  const rows: TItem[][] = [];
+  for (let i = 0; i < items.length; i += size) rows.push(items.slice(i, i + size));
+  return rows;
+};
+
+/**
+ * Organism — the PDP product image/video gallery (SFCC-731). Desktop (≥1280px) renders a
+ * stacked editorial column with a trailing 2x2 supporting-shot grid; tablet and mobile share a
+ * single-image swipeable carousel with dot navigation. Both breakpoints support
+ * click-anywhere-to-open-the-full-gallery, confirmed against the Figma design walkthrough.
+ *
+ * Reusable beyond the PDP — takes a plain `media` sequence rather than the raw SFCC
+ * `imageGroups` shape, so a caller maps its own product data at the call site (see
+ * `product-view/index.tsx` for the PDP's mapping from `product.imageGroups`).
+ */
+export const ZimmProductGallery = ({
+  media,
+  onOpenGallery,
+  lazy = false,
+  showGalleryButton = true,
+  imageQuality,
+}: ZimmProductGalleryProps) => {
+  const intl = useIntl();
+  const styles = useMultiStyleConfig(ZIMM_PRODUCT_GALLERY_RECIPE, {});
+
+  const [selectedIndex, setSelectedIndex] = useState(0);
+  const trackRef = useRef<HTMLDivElement>(null);
+  const slideRefs = useRef<Array<HTMLDivElement | null>>([]);
+
+  // Clamped for every read below (render-time, so there's no frame where a stale index reads
+  // past the end) — a variation swap can replace `media` with a shorter array without
+  // `selectedIndex` (state, from before the swap) ever being told to catch up. Without this, an
+  // out-of-bounds index makes every slide `i !== safeSelectedIndex` true, i.e. every slide goes
+  // inert at once, and the live region announces a position that doesn't exist (CodeRabbit, PR #81).
+  const safeSelectedIndex = Math.min(selectedIndex, Math.max(0, media.length - 1));
+  // Corrects the underlying state too, so later interactions (dot nav, scrollToSlide) aren't
+  // still working off a stale value once media stabilises.
+  useEffect(() => {
+    setSelectedIndex((prev) => Math.min(prev, Math.max(0, media.length - 1)));
+  }, [media.length]);
+
+  // Tracks which slide is most visible in the compact carousel as the shopper swipes — native
+  // browser scroll-snap handles the gesture itself (see zimmProductGallery.css.ts's
+  // compactTrack), this just keeps the dots and the last-slide-only button in sync with it.
+  useEffect(() => {
+    const track = trackRef.current;
+    if (!track) return;
+
+    const observer = new IntersectionObserver(
+      (entries) => {
+        const mostVisible = entries
+          .filter((e) => e.isIntersecting)
+          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
+        if (!mostVisible) return;
+        const index = slideRefs.current.indexOf(mostVisible.target as HTMLDivElement);
+        if (index >= 0) setSelectedIndex(index);
+      },
+      { root: track, threshold: 0.5 },
+    );
+
+    slideRefs.current.forEach((slide) => slide && observer.observe(slide));
+    return () => observer.disconnect();
+  }, [media.length]);
+
+  // All slides stay mounted for native scroll-snap, so without this a screen reader's swipe/
+  // read-order encounters every offscreen slide's alt text and controls, not just the current
+  // one. `inert` removes the rest from both the accessibility tree and keyboard/pointer reach —
+  // one attribute instead of separately managing aria-hidden and each control's tabIndex.
+  useEffect(() => {
+    slideRefs.current.forEach((slide, i) => {
+      if (slide) slide.inert = i !== safeSelectedIndex;
+    });
+  }, [safeSelectedIndex, media.length]);
+
+  const scrollToSlide = (index: number) => {
+    slideRefs.current[index]?.scrollIntoView({ behavior: 'smooth', inline: 'start', block: 'nearest' });
+  };
+
+  // Each dot stays its own independent Tab stop (not roving tabindex) — arrow keys are an
+  // addition alongside Tab, not a replacement for it. Moves focus only; Enter/Space still
